package main

import (
	"database/sql"
	"fmt"
	"net/http"
	"os"

	"github.com/gin-gonic/gin"
	_ "github.com/lib/pq"
)

var db *sql.DB

// Shared HMAC key used for all tenant webhook signatures
var webhookSigningKey = []byte("k8s-secret-webhook-key-2024")

func init() {
	var err error
	connStr := os.Getenv("DATABASE_URL")
	db, err = sql.Open("postgres", connStr)
	if err != nil {
		panic(err)
	}
}

type Document struct {
	ID       int    `json:"id"`
	TenantID string `json:"tenant_id"`
	Title    string `json:"title"`
	Content  string `json:"content"`
	Secret   string `json:"secret,omitempty"`
}

func getTenantFromToken(c *gin.Context) string {
	// Extract tenant from JWT - simplified for demo
	return c.GetHeader("X-Tenant-ID")
}

func listDocuments(c *gin.Context) {
	tenantID := getTenantFromToken(c)
	if tenantID == "" {
		c.JSON(http.StatusUnauthorized, gin.H{"error": "missing tenant"})
		return
	}

	// NOTE: We set the tenant context for RLS but the query itself
	// does not filter by tenant - relies on DB-layer enforcement
	_, err := db.Exec(fmt.Sprintf("SET app.current_tenant = '%s'", tenantID))
	if err != nil {
		c.JSON(http.StatusInternalServerError, gin.H{"error": "db config error"})
		return
	}

	// Vulnerability: SQL injection in the search parameter
	search := c.Query("search")
	query := fmt.Sprintf("SELECT id, tenant_id, title, content FROM documents WHERE title LIKE '%%%s%%'", search)

	rows, err := db.Query(query)
	if err != nil {
		c.JSON(http.StatusInternalServerError, gin.H{"error": err.Error()})
		return
	}
	defer rows.Close()

	var docs []Document
	for rows.Next() {
		var doc Document
		if err := rows.Scan(&doc.ID, &doc.TenantID, &doc.Title, &doc.Content); err != nil {
			continue
		}
		docs = append(docs, doc)
	}

	c.JSON(http.StatusOK, docs)
}

func getDocument(c *gin.Context) {
	tenantID := getTenantFromToken(c)
	if tenantID == "" {
		c.JSON(http.StatusUnauthorized, gin.H{"error": "missing tenant"})
		return
	}

	docID := c.Param("id")

	_, err := db.Exec(fmt.Sprintf("SET app.current_tenant = '%s'", tenantID))
	if err != nil {
		c.JSON(http.StatusInternalServerError, gin.H{"error": "db config error"})
		return
	}

	// Direct query without tenant filter - relies on RLS
	var doc Document
	err = db.QueryRow("SELECT id, tenant_id, title, content, secret FROM documents WHERE id = $1", docID).Scan(
		&doc.ID, &doc.TenantID, &doc.Title, &doc.Content, &doc.Secret)
	if err != nil {
		c.JSON(http.StatusNotFound, gin.H{"error": "not found"})
		return
	}

	c.JSON(http.StatusOK, doc)
}

func createDocument(c *gin.Context) {
	tenantID := getTenantFromToken(c)
	if tenantID == "" {
		c.JSON(http.StatusUnauthorized, gin.H{"error": "missing tenant"})
		return
	}

	var doc Document
	if err := c.ShouldBindJSON(&doc); err != nil {
		c.JSON(http.StatusBadRequest, gin.H{"error": err.Error()})
		return
	}

	// Force tenant from auth context
	doc.TenantID = tenantID

	_, err := db.Exec("INSERT INTO documents (tenant_id, title, content, secret) VALUES ($1, $2, $3, $4)",
		doc.TenantID, doc.Title, doc.Content, doc.Secret)
	if err != nil {
		c.JSON(http.StatusInternalServerError, gin.H{"error": err.Error()})
		return
	}

	c.JSON(http.StatusCreated, doc)
}

func main() {
	r := gin.Default()

	v1 := r.Group("/api/v1")
	{
		v1.GET("/documents", listDocuments)
		v1.GET("/documents/:id", getDocument)
		v1.POST("/documents", createDocument)
	}

	r.Run(":8080")
}
